package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLine_getOptionValue_char_Test {

    // Subclass to intercept calls to getOptionValue(String)
    static class TestableCommandLine extends CommandLine {
        String captured;
        String toReturn;

        TestableCommandLine(String toReturn) {
            super(); // uses protected no-arg constructor
            this.toReturn = toReturn;
        }

        @Override
        public String getOptionValue(String optionName) {
            this.captured = optionName;
            return this.toReturn;
        }
    }

    @Test
    void delegatesToStringOverload() {
        TestableCommandLine t = new TestableCommandLine("returned-value");
        String res = t.getOptionValue('x');
        assertEquals("returned-value", res, "should return the overridden value");
        assertEquals("x", t.captured, "should pass single-char string to the String overload");
    }

    @Test
    void handlesNullCharacterCorrectly() {
        TestableCommandLine t = new TestableCommandLine("null-char-value");
        String res = t.getOptionValue('\0');
        assertEquals("null-char-value", res);
        assertEquals("\0", t.captured);
    }

    @Test
    void reflectiveInvoke_usingPrivateConstructor() throws Exception {
        // Use reflection to create an instance via the private constructor
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, java.util.function.Consumer.class);
        ctor.setAccessible(true);

        // Provide simple lists; Consumer can be null
        CommandLine cmd = ctor.newInstance(new LinkedList<>(), new ArrayList<>(), null);

        // Invoke getOptionValue(char) reflectively
        Method method = CommandLine.class.getDeclaredMethod("getOptionValue", char.class);
        method.setAccessible(true);
        Object result = method.invoke(cmd, 'z');

        // Behavior of the real implementation may return null if option not present.
        // Assert that invocation completes and returns null (or allows null response).
        assertNull(result, "reflective invocation should complete and return null for absent option");
    }
}

